        try:
            return session.execute(command)
        except Exception as e:
            # 自动重连
            session.connect()
            return session.execute(command)

    def cleanup(self):
        """清理空闲会话"""
        for sid, session in list(self.sessions.items()):
            if not session.keepalive():
                session.close()
                del self.sessions[sid]
