        previous = lines[probe - 1].strip()
        if previous.startswith(("#", "@")):
            probe -= 1
            start = probe
        elif previous == "" and probe >= 2 and lines[probe - 2].strip().startswith(("#", "@")):
            probe -= 1
        else:
            break
    return start

