  *)      echo "用法: $0 start|stop|status|log" ;;
esac

def load_tier(tier: str, config: dict[str, Any]) -> Store | None:
    """读某一层的索引; 文件不存在返回 None. 结果缓存."""
    if tier not in _CACHE:
        _, path = resolve_tier(config, tier)
        _CACHE[tier] = load_index(path) if path.is_file() else None
    return _CACHE[tier]

