    table = cast(dict[str, Any], tiers)
    entry = table.get(tier)
    if not isinstance(entry, dict):
        raise ValueError(f"配置里没有这一层: {tier}  (可选 {sorted(table)})")
    row = cast(dict[str, Any], entry)
